package main

import (
	"errors"
	"fmt"
	"slices"
	"sort"
	"strings"
	"sync"
)

type Pair[K comparable, V any] struct {
	Key K
	Val V
}

func (p Pair[K, V]) String() string { return fmt.Sprintf("%v=%v", p.Key, p.Val) }

type Set[T comparable] struct{ m map[T]struct{} }

func NewSet[T comparable]() *Set[T] { return &Set[T]{m: map[T]struct{}{}} }
func (s *Set[T]) Add(v T)            { s.m[v] = struct{}{} }
func (s *Set[T]) Has(v T) bool {
	_, ok := s.m[v]
	return ok
}
func (s *Set[T]) Len() int { return len(s.m) }

var ErrNotFound = errors.New("not found")

type QueryErr struct{ Q string }

func (e *QueryErr) Error() string        { return "query " + e.Q }
func (e *QueryErr) Is(target error) bool { return target == ErrNotFound }

func producer(n int, out chan<- int) {
	for i := 1; i <= n; i++ {
		out <- i
	}
	close(out)
}

func square(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for v := range in {
			out <- v * v
		}
	}()
	return out
}

func main() {
	ch := make(chan int)
	go producer(4, ch)
	total := 0
	for v := range square(ch) {
		total += v
	}
	fmt.Println("sum of squares", total)

	var mu sync.Mutex
	var wg sync.WaitGroup
	results := []string{}
	for i := 0; i < 4; i++ {
		wg.Go(func() {
			mu.Lock()
			defer mu.Unlock()
			results = append(results, fmt.Sprintf("job%d", i))
		})
	}
	wg.Wait()
	sort.Strings(results)
	fmt.Println(strings.Join(results, ","))

	jobs := make(chan int, 5)
	done := make(chan []int)
	go func() {
		var got []int
		for j := range jobs {
			got = append(got, j*10)
		}
		done <- got
	}()
	for i := range 5 {
		jobs <- i
	}
	close(jobs)
	fmt.Println(<-done)

	timeout := make(chan bool, 1)
	data := make(chan string, 1)
	data <- "payload"
	select {
	case d := <-data:
		fmt.Println("received", d)
	case <-timeout:
		fmt.Println("timeout")
	}

	ps := []Pair[string, int]{{"b", 2}, {"a", 1}}
	slices.SortFunc(ps, func(x, y Pair[string, int]) int { return strings.Compare(x.Key, y.Key) })
	fmt.Println(ps, ps[0])
	s := NewSet[string]()
	s.Add("go")
	s.Add("go")
	s.Add("rust")
	fmt.Println(s.Has("go"), s.Has("c"), s.Len())

	err := fmt.Errorf("lookup: %w", &QueryErr{"users"})
	fmt.Println(err, errors.Is(err, ErrNotFound))
	var qe *QueryErr
	if errors.As(err, &qe) {
		fmt.Println("as", qe.Q)
	}
	counts := map[rune]int{}
	for _, r := range "hello world" {
		counts[r]++
	}
	fmt.Println(counts['l'], counts['o'], len(counts))
	matrix := [][]int{{1, 2, 3}, {4, 5, 6}}
	t := make([][]int, 3)
	for i := range t {
		t[i] = make([]int, 2)
		for j := range t[i] {
			t[i][j] = matrix[j][i]
		}
	}
	fmt.Println(t)
}

