type Level int

const (
	Low Level = iota
	High
)

func (l Level) String() string {
	switch l {
	case Low:
		return "low"
	case High:
		return "high"
	}
	return "unknown"
}

type Vec struct{ X, Y int }

func (v *Vec) String() string { return fmt.Sprintf("<%d,%d>", v.X, v.Y) }

type ValErr struct{ Code int }

func (e ValErr) Error() string { return fmt.Sprintf("code %d", e.Code) }

type Logger interface{ Log(string) }
type Service struct {
	Logger
	name string
}
type stdout struct{ prefix string }

func (s stdout) Log(m string) { fmt.Println(s.prefix + m) }

func safeDiv(a, b int) (q int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered: %v", r)
		}
	}()
	return a / b, nil
}

func Map[T, U any](xs []T, f func(T) U) []U {
	out := make([]U, 0, len(xs))
	for _, x := range xs {
		out = append(out, f(x))
	}
	return out
}

type Number interface{ ~int | ~float64 }

func Sum[T Number](xs ...T) T {
	var s T
	for _, x := range xs {
		s += x
	}
	return s
}

func walk(yield func(string) bool) {
	defer fmt.Println("walk cleanup")
	for _, s := range []string{"a", "b", "c"} {
		if !yield(s) {
			return
		}
	}
}

func main() {
	fmt.Println(Low, High, Level(7))
	fmt.Printf("%v %d %s|%5s|\n", High, High, Low, High)
	v := &Vec{1, 2}
	fmt.Println(v, *v)
	fmt.Printf("%v %+v\n", v, *v)
	var err error = ValErr{42}
	fmt.Println(err)
	var target ValErr
	wrapped := fmt.Errorf("op: %w", err)
	fmt.Println(errors.As(wrapped, &target), target.Code)
	switch e := err.(type) {
	case ValErr:
		fmt.Println("ValErr", e.Code)
	}
	svc := Service{stdout{"> "}, "svc"}
	svc.Log("hello from " + svc.name)
	var lg Logger = svc
	lg.Log("via interface")
	q, err := safeDiv(1, 0)
	fmt.Println(q, err)
	fmt.Println(Map([]int{1, 2, 3}, func(i int) string { return strings.Repeat("*", i) }))
	fmt.Println(Sum(1, 2, 3), Sum(1.5, 2.25))
	for s := range walk {
		if s == "b" {
			break
		}
		fmt.Println("got", s)
	}
	var fs []func() int
	for i := 0; i < 3; i++ {
		fs = append(fs, func() int { return i * i })
	}
	for _, f := range fs {
		fmt.Print(f(), " ")
	}
	fmt.Println()
	d := 1500 * time.Millisecond
	fmt.Println(d, 2*time.Hour+3*time.Minute, 250*time.Microsecond, time.Duration(0))
	fmt.Printf("%v|%s|%d\n", d, d, d)
	m := map[string][]int{"b": {2}, "a": {1, 1}}
	m["a"] = append(m["a"], 9)
	fmt.Println(m, len(m["a"]))
	type key struct{ a, b int }
	seen := map[key]bool{{1, 2}: true}
	fmt.Println(seen[key{1, 2}], seen[key{2, 1}], key{1, 2} == key{1, 2})
	word := "héllo"
	for i, r := range word {
		if r == 'l' {
			continue
		}
		fmt.Print(i, ":", string(r), " ")
	}
	fmt.Println()
	x := 3
	switch {
	case x > 2:
		fmt.Println("big")
		fallthrough
	case x > 100:
		fmt.Println("fell")
	default:
		fmt.Println("no")
	}
	var sb strings.Builder
	for i := 3; i > 0; i-- {
		fmt.Fprintf(&sb, "%d...", i)
	}
	sb.WriteString("go!")
	fmt.Println(sb.String())
	fmt.Printf("%6.2f|%-8s|%x|%08b|%3c|%q\n", 3.14159, "left", 3054, 5, 'A', 'z')
	fmt.Printf("%v %v\n", []any{1, "a", nil, 2.5}, [2][]int{{1}, {2, 3}})
	var np *Vec
	fmt.Println(np == nil, np)
}

