)

type Animal struct{ Name string }

func (a Animal) Speak() string { return a.Name + " makes a sound" }
func (a *Animal) Rename(n string) { a.Name = n }

type Dog struct {
	Animal
	Breed string
}

type Puppy struct {
	*Dog
	Age int
}

type Speaker interface{ Speak() string }

type Counter struct {
	sync.Mutex
	n int
}

func main() {
	d := Dog{Animal{"Rex"}, "lab"}
	fmt.Println(d.Name, d.Speak(), d.Animal.Name)
	d.Rename("Max")
	fmt.Println(d.Name)
	d.Name = "Bo"
	fmt.Println(d.Animal.Name)
	var s Speaker = d
	fmt.Println(s.Speak())
	p := Puppy{&d, 1}
	fmt.Println(p.Name, p.Speak(), p.Breed)
	p.Rename("Pip")
	fmt.Println(d.Name)
	pd := &d
	fmt.Println(pd.Speak(), pd.Name)
	var c Counter
	c.Lock()
	c.n++
	c.Unlock()
	fmt.Println(c.n)
	fmt.Printf("%+v\n", d)
}

