type node struct {
	next *node
	val  [4]int
}

func main() {
	var keep *node
	for i := 0; i < 120; i++ {
		n := &node{val: [4]int{i}}
		if i%20 == 0 {
			n.next = keep
			keep = n
		}
	}
	count := 0
	for p := keep; p != nil; p = p.next {
		count++
	}
	fmt.Println(keep.val[0], count)
}

