import (
	"fmt"
	"iter"
	"slices"
)

type Tree struct {
	Left, Right *Tree
	Val         int
}

func (t *Tree) All() iter.Seq[int] {
	return func(yield func(int) bool) {
		t.push(yield)
	}
}

func (t *Tree) push(yield func(int) bool) bool {
	if t == nil {
		return true
	}
	return t.Left.push(yield) && yield(t.Val) && t.Right.push(yield)
}

func Filter[T any](seq iter.Seq[T], keep func(T) bool) iter.Seq[T] {
	return func(yield func(T) bool) {
		for v := range seq {
			if keep(v) && !yield(v) {
				return
			}
		}
	}
}

func firstOver(t *Tree, n int) (found int) {
	found = -1
	for v := range t.All() {
		if v > n {
			found = v
			return
		}
	}
	return
}

func main() {
	t := &Tree{&Tree{nil, nil, 1}, &Tree{&Tree{nil, nil, 4}, nil, 7}, 3}
	for v := range t.All() {
		fmt.Print(v, " ")
	}
	fmt.Println()
	fmt.Println(slices.Collect(Filter(t.All(), func(v int) bool { return v%2 == 1 })))
	fmt.Println(firstOver(t, 3), firstOver(t, 100))
outer:
	for v := range t.All() {
		for w := range t.All() {
			if w > v {
				continue outer
			}
			if v == 7 {
				break outer
			}
			fmt.Print(v, w, ";")
		}
	}
	fmt.Println()
	i := 0
loop:
	if i < 5 {
		i += 2
		goto loop
	}
	fmt.Println("i", i)
	n := 0
	for {
		n++
		if n > 3 {
			goto done
		}
	}
done:
	fmt.Println("n", n)
	count := 0
	defer func() { fmt.Println("deferred count", count) }()
	for range slices.Values([]int{1, 2, 3}) {
		count++
	}
}

package main

import (
	"fmt"
	"iter"
	"maps"
	"slices"
)

func Count(n int) func(func(int) bool) {
	return func(yield func(int) bool) {
		for i := 0; i < n; i++ {
			if !yield(i) {
				fmt.Println("stopped at", i)
				return
			}
		}
		fmt.Println("finished")
	}
}

func Pairs(words []string) iter.Seq2[int, string] {
	return func(yield func(int, string) bool) {
		for i, w := range words {
			if !yield(i, w) {
				return
			}
		}
	}
}

func Evens(xs []int) iter.Seq[int] {
	return func(yield func(int) bool) {
		for _, x := range xs {
			if x%2 == 0 && !yield(x) {
				return
			}
		}
	}
}

func three(yield func() bool) {
	for i := 0; i < 3; i++ {
		if !yield() {
			return
		}
	}
}

func find(n int) int {
	for x := range Count(10) {
		if x == n {
			return x * 100
		}
	}
	return -1
}

func main() {
	for x := range Count(3) {
		fmt.Println("x", x)
	}
	for x := range Count(10) {
		if x == 2 {
			break
		}
		if x == 0 {
			continue
		}
		fmt.Println("y", x)
	}
	for i, w := range Pairs([]string{"a", "b", "c"}) {
		fmt.Println(i, w)
	}
	n := 0
	for range three {
		n++
	}
	fmt.Println("three", n)
	fmt.Println(find(4))
	fmt.Println(slices.Collect(Evens([]int{1, 2, 3, 4, 6})))
	m := map[string]int{"b": 2, "a": 1, "c": 3}
	keys := slices.Sorted(maps.Keys(m))
	fmt.Println(keys)
	vals := slices.Sorted(maps.Values(m))
	fmt.Println(vals)
	for i, v := range slices.All([]string{"p", "q"}) {
		fmt.Println(i, v)
	}
	for v := range slices.Values([]int{7, 8}) {
		fmt.Println(v)
	}
	sum := 0
	for _, v := range maps.All(m) {
		sum += v
	}
	fmt.Println(sum)
}

