import "fmt"

func main() {
outer:
	for i := 0; i < 3; i++ {
		for j := 0; j < 3; j++ {
			if j == 2 {
				continue outer
			}
			if i == 2 {
				break outer
			}
			fmt.Println(i, j)
		}
	}
	ch := make(chan int, 3)
	ch <- 1
	ch <- 2
	ch <- 3
loop:
	for {
		select {
		case v := <-ch:
			if v == 2 {
				break loop
			}
			fmt.Println("got", v)
		}
	}
sw:
	switch x := 5; {
	case x > 3:
		for k := range 10 {
			if k == 1 {
				break sw
			}
			fmt.Println("k", k)
		}
		fmt.Println("unreached")
	}
	i := 0
again:
	if i < 3 {
		fmt.Println("goto", i)
		i++
		goto again
	}
	goto end
end:
	fmt.Println("done")
	n := 0
top:
	m := n * 2
	n++
	if n < 3 {
		goto top
	}
	fmt.Println(m, n)
}

