type NotFound struct{ Key string }

func (e *NotFound) Error() string { return "not found: " + e.Key }

type Temp float64

func (t Temp) String() string { return fmt.Sprintf("%.1f°C", float64(t)) }

type Wrapper struct{ err error }

func (w Wrapper) Error() string { return "wrapped: " + w.err.Error() }
func (w Wrapper) Unwrap() error { return w.err }

var ErrBase = errors.New("base")

func lookup(k string) error { return &NotFound{k} }

func main() {
	m := map[string]int{"zeta": 1, "alpha": 2, "mid": 3}
	fmt.Println(m)
	fmt.Println(map[int]bool{3: true, 1: false, 2: true})
	c := maps.Clone(m)
	c["new"] = 4
	fmt.Println(len(m), len(c))
	err := lookup("x")
	fmt.Println(err)
	var nf *NotFound
	wrapped := fmt.Errorf("layer: %w", err)
	fmt.Println(wrapped, errors.As(wrapped, &nf), nf.Key)
	w := Wrapper{ErrBase}
	fmt.Println(w, errors.Is(w, ErrBase), errors.Unwrap(w) == ErrBase)
	j := errors.Join(errors.New("one"), ErrBase)
	fmt.Println(j)
	fmt.Println(errors.Is(j, ErrBase), errors.Unwrap(j) == nil)
	two := fmt.Errorf("a: %w, b: %w", ErrBase, err)
	fmt.Println(two, errors.Is(two, ErrBase), errors.As(two, &nf))
	var t Temp = 21.5
	fmt.Println(t)
	fmt.Printf("%v %s %.2f %d\n", t, t, float64(t), 3)
	temps := []Temp{1, 2}
	fmt.Println(temps)
	fmt.Fprintln(os.Stdout, "to stdout", 1)
	fmt.Fprintf(os.Stdout, "%s-%d\n", "fmt", 2)
	fmt.Fprint(os.Stdout, "x", 3, "\n")
	fmt.Fprintln(os.Stderr, "to stderr")
}

