package main

import (
	"fmt"
	"math"
	"unicode"
)

type (
	Celsius float64
	Grid    [2][2]int
)

type Stack[T any] struct{ items []T }

func (s *Stack[T]) Push(v T) { s.items = append(s.items, v) }
func (s *Stack[T]) Pop() T {
	v := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return v
}

type Node struct {
	Val  int
	Next *Node
}

func classify(n int) string {
	switch {
	case n < 0:
		return "neg"
	case n == 0:
		return "zero"
	default:
		return "pos"
	}
}

func loopForever() int {
	for {
		return 7
	}
}

func main() {
	type pair struct{ a, b int }
	ps := []pair{{1, 2}, {3, 4}}
	fmt.Println(ps, len(ps))
	var c Celsius = 36.6
	fmt.Println(c, math.Sqrt(16), math.Max(3, 7), math.Abs(-2.5), math.Floor(2.7), math.Ceil(2.1))
	fmt.Println(math.Pow(2, 10), math.MaxInt64, math.MinInt64, math.MaxInt32, math.Inf(1))
	fmt.Printf("%.4f %v\n", math.Pi, math.Round(2.5))
	fmt.Println(unicode.IsUpper('A'), unicode.IsDigit('5'), unicode.IsLetter('!'), unicode.IsSpace(' '), string(unicode.ToUpper('q')))
	s := &Stack[int]{}
	s.Push(1)
	s.Push(2)
	fmt.Println(s.Pop(), len(s.items))
	list := &Node{1, &Node{2, nil}}
	for n := list; n != nil; n = n.Next {
		fmt.Print(n.Val, " ")
	}
	fmt.Println()
	fmt.Println(classify(-1), classify(0), classify(5), loopForever())
	var g Grid
	g[1][0] = 5
	fmt.Println(g)
	x, y := 10, 3
	fmt.Println(x/y, x%y, float64(x)/float64(y))
	r := []rune("héllo")
	fmt.Println(len(r), string(r[1]))
}

