package main

import (
	"errors"
	"fmt"
)

type Shape interface{ Area() float64 }
type Sq struct{ s float64 }

func (q Sq) Area() float64 { return q.s * q.s }

func describe(x any) string {
	switch v := x.(type) {
	case nil:
		return "nil"
	case int:
		return fmt.Sprintf("int %d", v+1)
	case string, error:
		return fmt.Sprintf("text-ish %v", v)
	case []int:
		return fmt.Sprintf("slice len %d", len(v))
	case Shape:
		return fmt.Sprintf("shape %.1f", v.Area())
	case *Sq:
		return "pointer to Sq"
	default:
		return fmt.Sprintf("other %T", v)
	}
}

func main() {
	for _, x := range []any{nil, 41, "hi", errors.New("boom"), []int{1, 2}, Sq{2}, &Sq{1}, 2.5, true} {
		fmt.Println(describe(x))
	}
	var y any = 7
	switch y.(type) {
	case string:
		fmt.Println("string")
	case int, int64:
		fmt.Println("integer")
	}
	switch z := y.(type) {
	default:
		fmt.Println("default", z)
	}
}
